/* @autogenerated */
package net.civeira.phylax.features.notification.outbox.domain.model;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link OutboundMail}.
 */
class OutboundMailTest {

  @Test
  @DisplayName("Builder sets all fields and getters return expected values")
  void build_withAllFields_returnsCorrectValues() {
    OutboundMail mail = OutboundMail.builder().recipient("user@example.com").subject("Hello")
        .htmlContent("<p>World</p>").textContent("World").build();

    Assertions.assertEquals("user@example.com", mail.getRecipient());
    Assertions.assertEquals("Hello", mail.getSubject());
    Assertions.assertEquals("<p>World</p>", mail.getHtmlContent());
    Assertions.assertEquals("World", mail.getTextContent());
    Assertions.assertEquals(Optional.of("Hello"), mail.getSubjectOptional());
    Assertions.assertEquals(Optional.of("World"), mail.getTextContentOptional());
  }

  @Test
  @DisplayName("getSubjectOptional returns empty when subject is null")
  void getSubjectOptional_returnsEmptyWhenNull() {
    OutboundMail mail =
        OutboundMail.builder().recipient("user@example.com").htmlContent("<p>Hi</p>").build();

    Assertions.assertTrue(mail.getSubjectOptional().isEmpty());
  }

  @Test
  @DisplayName("getTextContentOptional returns empty when textContent is null")
  void getTextContentOptional_returnsEmptyWhenNull() {
    OutboundMail mail = OutboundMail.builder().recipient("user@example.com").subject("Hi")
        .htmlContent("<p>Hi</p>").build();

    Assertions.assertTrue(mail.getTextContentOptional().isEmpty());
  }
}
